  const latestMutation = await c.env.DB.prepare(
    `SELECT MAX(sequence) AS sequence
     FROM account_mutations
     WHERE account_id = ?`
  ).bind(authContext.accountId).first();
  const nextSequence = (latestMutation?.sequence ?? 0) + 1;
  const currentItem = await c.env.DB.prepare(
    `SELECT quantity
     FROM account_items
     WHERE account_id = ? AND item_id = ?`
  ).bind(authContext.accountId, launchLoginBonusRewardLine.id).first();
  const launchBinding = await readEconomyBinding(c.env.DB);
  const launchPlan = await prepareLaunchRewards(c.env.DB, authContext.accountId, launchLoginBonusId, [launchLoginBonusRewardLine], launchBinding !== null);
  if (launchPlan.sources.length === 0) {
    const committed = await c.env.DB.prepare("SELECT reward_transaction_id,claimed_at,reward_json FROM account_login_bonus_claims WHERE account_id=? AND bonus_id=?").bind(authContext.accountId, launchLoginBonusId).first();
    if (committed) return c.json(createLoginBonusClaimReplayResponse({
      claimStatus: "ALREADY_CLAIMED",
      loginBonusClaimId: committed.reward_transaction_id,
      rewardJson: committed.reward_json,
      serverClaimedAt: committed.claimed_at
    }));
    return c.json(createLoginBonusClaimRejectedResponse({ errorCode: "launch_source_consumed", message: "Launch source was already consumed." }), 409);
  }
